referenceSolutions.javascript:
export function firstBadVersion(badFlags           )         {
  let low=0,high=badFlags.length; while(low<high) { const middle=low+Math.floor((high-low)/2); if(badFlags[middle])high=middle;else low=middle+1; } return low===badFlags.length?-1:low+1;
}

